#include <bits/stdc++.h>

using namespace std;

#define rep(i, n) for(int i = 0; i < n; ++i)
#define N 101
#define M 101
#define S 10001
#define INF (long long)1e+16

int main() {
	int n,m;
	int x;
	long long y;
	int a[N];
	int r[M]={};
	vector<pair<int,long long> >b;
	long long dp[M][S];

	cin>>n>>m;
	for(int i=0;i<n;i++)cin>>a[i];
	for(int i=0;i<m;i++){
		cin>>x>>y;
		b.push_back({x,y});
	}
	sort(b.rbegin(),b.rend());
	for(int i=0;i<m;i++){
		r[i+1]=0;
		for(int j=0;j<n;j++)r[i+1]+=min(i+1,a[j]);
	}

	for(int i=0;i<=m;i++)for(int j=0;j<=(n*m);j++)dp[i][j]=-INF;
	dp[0][0]=0;
	int s=0;
	rep(ii,m){
		s+=b[ii].first;
		for(int i=ii+1;i>=1;i--){
			int mx =min(s,r[i]);
			for(int j=b[ii].first;j<=mx;j++){
				dp[i][j]=max(dp[i][j],dp[i-1][j-b[ii].first]+b[ii].second);
			}
		}
	}

	long long ans=0;
	for(int i=0;i<=m;i++)for(int j=0;j<=(n*m);j++)ans=max(ans,dp[i][j]);
	cout<<ans<<endl;

	return 0;
}
